def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]
    marks = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg]
    if not marks:
        return [row[:] for row in grid]

    rmin = min(r for r, c in marks)
    rmax = max(r for r, c in marks)
    cmin = min(c for r, c in marks)
    cmax = max(c for r, c in marks)
    out = [row[:] for row in grid]

    # Draw the enclosing rectangle.
    for r in range(rmin, rmax + 1):
        for c in range(cmin, cmax + 1):
            if r in (rmin, rmax) or c in (cmin, cmax):
                if grid[r][c] == bg:
                    out[r][c] = 2

    # Extend vertically aligned marks through the rectangle.
    counts = {}
    for r, c in marks:
        counts[c] = counts.get(c, 0) + 1
    for c, count in counts.items():
        if count >= 2:
            for r in range(rmin, rmax + 1):
                if grid[r][c] == bg:
                    out[r][c] = 2

    return out
